import assert from 'node:assert/strict';
import {prepareGetterProgram} from '../tests/helpers/native-getter-invocation-fixture.ts';
import {REALM_CALL_SOURCE} from '../tests/helpers/native-realm-source-integration.ts';
import {replayOptions} from '../tests/helpers/ir-whole-program-replay.ts';
import {acceptPreparedIrProgram,emitAcceptedIrProgram} from '../src/ir/program-consumer.ts';
import {emitBinary} from '../src/emit/binary.ts';
const program=prepareGetterProgram(REALM_CALL_SOURCE);
const options=replayOptions('wasmgc','standalone');
const accepted=acceptPreparedIrProgram(program,options);
assert.equal(accepted.kind,'accepted');
if(accepted.kind!=='accepted')throw Error(JSON.stringify(accepted));
const module=new WebAssembly.Module(emitBinary(emitAcceptedIrProgram(accepted).module));
const output=(new WebAssembly.Instance(module).exports.run as ()=>number)();
assert.equal(output,94);assert.equal(WebAssembly.Module.imports(module).length,0);
console.log(JSON.stringify({case:'resolved-required-options',kind:'accepted',options,output,imports:[]}));
let error:unknown;
try{acceptPreparedIrProgram(program,{backend:'wasmgc',target:'standalone'} as any);}catch(e){error=e;}
assert(error instanceof Error);assert.match(error.message,/foreign, copied or substituted literal plan/);
console.log(JSON.stringify({case:'incomplete-options-not-supported-api-input',error:error.message,interpretation:'S7-w source probes omitted required utf8Storage; their literal-plan errors do not establish a normal consumer ownership bug.'}));
